 path='index.html' if fr else 'en/index.html';r=lambda x:rel(path,x);edu=r('education/index.html' if fr else 'en/education/index.html')
 services=[('emg','emg','Électromyographie (EMG)','Electromyography (EMG)','Étude des nerfs et des muscles pour préciser certaines atteintes neuromusculaires.','Nerve and muscle testing to help clarify neuromuscular conditions.'),('echographie','spasticite','Échographie diagnostique','Diagnostic ultrasound','Évaluation des muscles, tendons, articulations et nerfs en temps réel.','Real-time assessment of muscles, tendons, joints and nerves.'),('infiltrations','infiltrations','Infiltrations échoguidées','Ultrasound-guided injections','Articulations, tendons et nerfs; cortisone, viscosupplémentation ou PRP selon l’indication.','Joints, tendons and nerves; corticosteroid, viscosupplementation or PRP when appropriate.'),('toxine-botulinique','migraine','Toxine botulinique','Botulinum toxin','Évaluation et injections notamment pour la spasticité et la migraine chronique.','Assessment and injections, including for spasticity and chronic migraine.')]
