 mapurl='https://www.google.com/maps/search/?'+urlencode({'api':'1','query':C['street']+' '+C['city']})
 body=f'''<main id="main"><div class="wrap hero"><div><p class="eyebrow">{t('Dr Andrei Bursuc · Physiatre','Dr Andrei Bursuc · Physiatrist')}</p><h1>{t('Médecine physique<br>& réadaptation.','Physical medicine<br>& rehabilitation.')}</h1><p class="intro">{t('Une pratique axée sur la médecine neuro-musculosquelettique, la mobilité et l’autonomie.','A practice focused on neuromusculoskeletal medicine, mobility and independence.')}</p><div class="hero-contact" id="consultations"><h2>{t('Demande de consultation','Consultation referral')}</h2><p class="referral-intro">{t('Pour adresser un patient au Dr Bursuc, le médecin référent peut remplir le formulaire et le transmettre par fax.','To refer a patient to Dr Bursuc, the referring physician can complete the form and send it by fax.')}</p><div class="actions"><a class="button" href="{r(C['referralPdf'])}" download>{t('Télécharger le formulaire de consultation (PDF)','Download the consultation referral form (PDF)')}</a></div><p class="referral-fax">{t('Fax des références :','Referral fax:')} <strong>{esc(C['referralFax'])}</strong></p><p class="referral-next">{t('Après réception, la demande est évaluée. Si une consultation peut être offerte, le patient sera contacté pour les prochaines étapes.','After the referral is received, it is reviewed. If a consultation can be offered, the patient will be contacted about next steps.')}</p><div class="clinic-location"><h3>{t('Lieu de consultation','Clinic location')}</h3><p><strong>{esc(C['name'])}</strong><br>{esc(C['street'])}<br>{esc(C['city'])}</p><a href="{esc(mapurl,quote=True)}">{t('Itinéraire','Directions')}</a></div></div></div><div class="portrait-frame"><img src="{r('assets/portrait.jpg')}" alt="{t('Portrait du Dr Andrei Bursuc','Portrait of Dr Andrei Bursuc')}" width="650" height="715" fetchpriority="high"><div class="portrait-caption"><strong>Andrei Bursuc</strong>{D['credentials']} · {t('Physiatre','Physiatrist')}</div></div></div><section class="section wrap" id="services"><div class="section-head"><div><p class="eyebrow">{t('Domaines de pratique','Areas of practice')}</p><h2>{t('Une approche neuro-MSK.','A neuro-MSK approach.')}</h2></div><p>{t('Évaluation et traitements en médecine physique et réadaptation.','Assessment and treatment in physical medicine and rehabilitation.')}</p></div><div class="services">{cards}</div><p class="note">{t('Une référence médicale est requise. Le médecin référent peut utiliser le formulaire ci-dessus pour transmettre sa demande par fax.','A physician referral is required. The referring physician can use the form above and send the request by fax.')}</p></section><section class="section soft" id="parcours"><div class="wrap about"><div><p class="eyebrow">{t('Parcours','Background')}</p><h2>{t('Dr Andrei Bursuc','Dr Andrei Bursuc')}</h2></div><div class="about-text"><p>{t('Spécialiste en médecine physique et réadaptation, le Dr Bursuc exerce à Montréal à la Clinique de physiatrie CDN. Sa pratique comprend l’électromyographie, la gestion de la spasticité et les infiltrations échoguidées.','A specialist in physical medicine and rehabilitation, Dr Bursuc practises in Montréal at Clinique de physiatrie CDN. His practice includes electromyography, spasticity management and ultrasound-guided injections.')}</p><ul class="training"><li><strong>{t('Doctorat en médecine','Doctor of Medicine')}</strong><span>Université de Montréal</span></li><li><strong>{t('Spécialité en médecine physique et réadaptation','Specialty in Physical Medicine and Rehabilitation')}</strong><span>Université de Montréal</span></li><li><strong>{t('Maîtrise en médecine expérimentale','Master of Science in Experimental Medicine')}</strong><span>McGill University</span></li><li><strong>{t('Surspécialisation en échographie neuromusculosquelettique et en évaluation neuro-orthopédique et neuromusculaire','Subspecialization in neuromusculoskeletal ultrasound and neuro-orthopaedic and neuromuscular assessment')}</strong><span>{t('Hôpital Raymond-Poincaré, Garches, France · AP-HP. Université Paris-Saclay','Raymond-Poincaré Hospital, Garches, France · AP-HP. Université Paris-Saclay')}</span></li></ul></div></div></section><section class="section wrap"><div class="education-callout"><div><p class="eyebrow">{t('Pour les professionnels et les étudiants','For clinicians and students')}</p><h2>{t('Explorer. Comprendre.<br>Apprendre.','Explore. Understand.<br>Learn.')}</h2><p>{t('Des outils interactifs pour approfondir l’anatomie, la localisation neurologique et les techniques en neuro-orthopédie.','Interactive tools to explore anatomy, neurological localization and neuro-orthopaedic techniques.')}</p><a class="button actions" href="{edu}">{t('Accéder aux outils d’éducation','Open the education tools')} <span aria-hidden="true">↗</span></a></div><ul class="edu-list"><li>{t('Explorateurs des nerfs · membres supérieurs et inférieurs','Nerve explorers · upper and lower limbs')}</li><li>{t('Territoires des blocs moteurs','Motor block territories')}</li><li>{t('Muscles et vidéos en échographie','Muscle ultrasound and videos')}</li></ul></div></section></main>'''
 body=body.replace('</main>',faq_teaser(lang, r('faq/index.html' if fr else 'en/faq/index.html')+'?v=20261018-faq3')+'</main>')
