def service_pages(lang):
 fr=lang=='fr';t=lambda f,e:f if fr else e
 for slug,title_fr,title_en,kicker_fr,kicker_en,intro_fr,intro_en,h1_fr,h1_en,p1_fr,p1_en,h2_fr,h2_en,p2_fr,p2_en in SERVICE_PAGES:
  path=('services/' if fr else 'en/services/')+slug+'/index.html';r=lambda x:rel(path,x)
  home='index.html' if fr else 'en/index.html'
  other=('en/services/' if fr else 'services/')+slug+'/index.html'
  body=f'''<main id="main"><section class="service-hero"><div class="wrap"><a class="back" href="{r(home)}#services">← {t('Toutes les expertises','All services')}</a><p class="eyebrow">{t('Consultations en physiatrie · Montréal','Physiatry consultations · Montréal')}</p><h1>{t(title_fr,title_en)}</h1><p class="service-lead">{t(intro_fr,intro_en)}</p></div></section><section class="section wrap service-details"><div class="service-detail"><h2>{t(h1_fr,h1_en)}</h2><p>{t(p1_fr,p1_en)}</p></div><div class="service-detail"><h2>{t(h2_fr,h2_en)}</h2><p>{t(p2_fr,p2_en)}</p></div></section><section class="section soft"><div class="wrap service-referral"><div><p class="eyebrow">{t('Demande de consultation','Consultation referral')}</p><h2>{t('Faire parvenir une référence','Send a referral')}</h2><p>{t('Une référence médicale est requise. Le médecin référent peut remplir le formulaire et l’envoyer par fax au','A physician referral is required. The referring physician can complete the form and fax it to')} <strong>{esc(C['referralFax'])}</strong>.</p><p>{t('Après réception, la demande est évaluée. Si une consultation peut être offerte, le patient sera contacté pour les prochaines étapes.','After the referral is received, it is reviewed. If a consultation can be offered, the patient will be contacted about next steps.')}</p><a class="button" href="{r(C['referralPdf'])}" download>{t('Télécharger le formulaire de consultation (PDF)','Download the consultation referral form (PDF)')}</a></div></div></section></main>'''
  page(path,lang,t(title_fr+' à Montréal | Dr Andrei Bursuc',title_en+' in Montréal | Dr Andrei Bursuc'),t(intro_fr,intro_en),body,active='services',alternate=other)

